import { DownloadIcon, ImageIcon, PictureInPicture2Icon } from 'lucide-react'

import { BrowserChrome, DemoStage, DockHeader, Toggle, type Build } from '@/app/demos/stage'

import {
  CAPTION_BOLD,
  CAPTION_RAW,
  CAPTIONS,
  DEMO_SPEED,
  FEATURES,
  SPEED_LABELS,
  SPEEDS,
} from './script'

const speedIndex = SPEEDS.indexOf(DEMO_SPEED)

const build: Build = ({ tl, q, qa, step, final, move, click, wait, cursorOut }) => {
  const toggle = (id: string) => {
    move(id)
    click(id)
    tl.to(q(`${id}-fill`), { opacity: 1, duration: 0.2 }, '<')
    tl.to(q(`${id}-knob`), { x: 12, duration: 0.25, ease: 'back.out(2)' }, '<')
  }

  step(0)
  toggle('videoControls')
  tl.fromTo(
    q('seek'),
    { opacity: 0, scaleX: 0.2 },
    { opacity: 1, scaleX: 1, duration: 0.55, ease: 'power3.out' },
    '<',
  )
  tl.fromTo(q('time'), { opacity: 0 }, { opacity: 1, duration: 0.3 }, '<0.2')

  step(1, '+=0.45')
  move('speed')
  click('speed')
  tl.to(q('speed-knob'), {
    left: `${(speedIndex / (SPEEDS.length - 1)) * 100}%`,
    duration: 0.45,
    ease: 'power2.inOut',
  })
  tl.to(q('speed-chip'), { opacity: 1, duration: 0.25 }, '<')
  tl.set(q('speed-chip'), { textContent: SPEED_LABELS[DEMO_SPEED] })

  step(2, '+=0.45')
  toggle('mediaDownload')
  toggle('pictureInPicture')
  tl.fromTo(
    qa('overlay-btn'),
    { opacity: 0, y: -6 },
    { opacity: 1, y: 0, stagger: 0.08, duration: 0.35 },
    '<',
  )

  step(3, '+=0.45')
  move('caption-bold')
  click('caption-bold')
  tl.fromTo(q('caption-out'), { opacity: 0 }, { opacity: 1, duration: 0.35 }, '<')
  tl.set(q('caption-out'), { textContent: CAPTION_BOLD })

  step(4, '+=0.45')
  toggle('ghostStories')
  tl.fromTo(q('ghost'), { opacity: 0 }, { opacity: 1, duration: 0.35 }, '<')
  cursorOut('<0.3')
  final()
  wait(0.7)
}

function Panel() {
  return (
    <div className="flex h-full flex-col">
      <DockHeader />
      <div className="flex flex-col gap-2 p-2.5">
        <div className="rounded-xl border border-line bg-white/[0.03] p-2.5">
          <div className="flex items-center justify-between gap-2">
            <span className="flex items-center gap-1.5">
              <ImageIcon className="size-4 text-pink-500" />
              <span className="text-[11px] font-semibold text-ink">Instagram Control Panel</span>
            </span>
            <Toggle on />
          </div>
          <p className="mt-1 text-[9.5px] text-muted">5 enhancements active</p>
        </div>
        <p className="text-[9.5px] font-semibold uppercase tracking-[0.12em] text-muted">Player</p>
        {FEATURES.filter((f) => f.section === 'Player').map((row) => (
          <div key={row.id} className="flex items-center justify-between text-[10px] text-ink-soft">
            {row.label}
            {row.id === 'playbackSpeed' ? (
              <span data-d="speed" className="relative h-4 w-16 rounded-full bg-line-strong">
                <span
                  data-d="speed-knob"
                  className="absolute top-0.5 size-3 -translate-x-1/2 rounded-full bg-[var(--accent)]"
                  style={{ left: `${(SPEEDS.indexOf('1') / (SPEEDS.length - 1)) * 100}%` }}
                />
              </span>
            ) : (
              <Toggle d={row.id} />
            )}
          </div>
        ))}
        <p className="mt-1 text-[9.5px] font-semibold uppercase tracking-[0.12em] text-muted">
          Download
        </p>
        <div className="flex items-center justify-between text-[10px] text-ink-soft">
          Media download button
          <Toggle d="mediaDownload" />
        </div>
        <p className="mt-1 text-[9.5px] font-semibold uppercase tracking-[0.12em] text-muted">
          Privacy
        </p>
        <div className="flex items-center justify-between text-[10px] text-ink-soft">
          Ghost story viewing
          <Toggle d="ghostStories" />
        </div>
        <div className="mt-2 rounded-lg border border-line bg-white/[0.03] p-2">
          <p className="text-[9.5px] font-semibold text-ink">Caption formatter</p>
          <p
            data-d="caption-out"
            className="mt-1 min-h-[2.5rem] break-words font-mono text-[9px] text-ink-soft"
          >
            {CAPTION_RAW.split('\n')[0]}
          </p>
          <div className="mt-2 flex flex-wrap gap-1">
            <span
              data-d="caption-bold"
              className="rounded-md bg-white/10 px-2 py-0.5 text-[9px] text-ink"
            >
              Bold Unicode
            </span>
          </div>
        </div>
      </div>
    </div>
  )
}

